export function ListFooter({
  summary = "{{summary}}",
  actionLabel = "{{actionLabel}}",
  style = "{{style}}",
  accent = "{{accent}}",
  showAction = {{showAction}},
}) {
  const footerStyle = {
    bar: { background: accent },
    minimal: { background: "transparent" },
    bordered: { background: "transparent", borderTop: `2px solid ${accent}` },
  }[style] ?? {};
  return (
    <div style={{ maxWidth: 360, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", borderRadius: 12, overflow: "hidden", border: "1px solid #24143020" }}>
      <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
        <li style={{ padding: "10px 16px", borderBottom: "1px solid #24143014" }}>Quarterly report.pdf</li>
        <li style={{ padding: "10px 16px", borderBottom: "1px solid #24143014" }}>Design specs.fig</li>
        <li style={{ padding: "10px 16px", borderBottom: "1px solid #24143014" }}>Roadmap notes.docx</li>
      </ul>
      <footer style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, padding: "12px 16px", ...footerStyle }}>
        <p style={{ margin: 0, fontSize: 12, color: "#24143099" }}>{summary}</p>
        {showAction && (
          <button type="button" style={{ border: `1.5px solid ${accent}`, background: "#FAF7F2", color: "#241430", padding: "6px 12px", borderRadius: 8, fontSize: 12, fontWeight: 600, cursor: "pointer" }}>
            {actionLabel}
          </button>
        )}
      </footer>
    </div>
  );
}
